+impl QeIdentity {
+    /// Verify the QE identity collateral and the policy encoded in it against
+    /// the QE report contained in the quote.
+    pub fn verify(
+        &self,
+        identity_json: &[u8],
+        identity_signature: &[u8],
+        issuer_chain: &[u8],
+        qe_report: &Report,
+    ) -> Result<()> {
+        // The QE identity is signed by the QE Identity Issuer.  Do not trust
+        // the JSON merely because it was obtained from PCCS.
+        verify_signature(
+            issuer_chain,
+            identity_json,
+            identity_signature,
+        )?;
+
+        let report = &qe_report.body;
+
+        // The QE report must satisfy the identity's attribute and
+        // miscselect policy.  These fields are masks, not exact values.
+        if (report.attributes & self.attributes_mask)
+            != (self.attributes & self.attributes_mask)
+        {
+            return Err(Error::InvalidQeIdentity);
+        }
+        if (report.misc_select & self.miscselect_mask)
+            != (self.miscselect & self.miscselect_mask)
+        {
+            return Err(Error::InvalidQeIdentity);
+        }
+
+        if report.mr_signer != self.mrsigner
+            || report.isv_prod_id != self.isv_prod_id
+        {
+            return Err(Error::InvalidQeIdentity);
+        }
+
+        // A QE report with an SVN below every accepted identity level must
+        // not be accepted.
+        if !self.tcb_levels.iter().any(|level| {
+            report.isv_svn >= level.tcb.isv_svn
+                && !matches!(
+                    level.tcb_status.as_str(),
+                    "Revoked" | "Invalid"
+                )
+        }) {
+            return Err(Error::InvalidQeIdentity);
+        }
+
+        Ok(())
+    }
